"""Outils qui captent et qualifient : calculateur de volume, checklist offerte."""
import build as b
from build import t,url,eyebrow

# Volumes indicatifs en m³ (ordres de grandeur courants du métier, confirmés ensuite par le conseiller)
ROOMS=[
 ('salon','Salon & salle à manger','Living & dining',[('Canapé 2 places','2-seater sofa',1.5),('Canapé 3 places','3-seater sofa',2),('Fauteuil','Armchair',0.8),('Table basse','Coffee table',0.3),('Meuble TV','TV unit',0.8),('Télévision','Television',0.2),('Bibliothèque','Bookcase',1.2),('Buffet ou bahut','Sideboard',1.5),('Table de salle à manger','Dining table',1),('Chaise','Chair',0.2),('Tapis roulé','Rolled rug',0.2),('Lampadaire ou plante','Floor lamp or plant',0.2)]),
 ('chambre','Chambres','Bedrooms',[('Lit simple et matelas','Single bed and mattress',1),('Lit double et matelas','Double bed and mattress',2),('Lit d’enfant','Child’s bed',0.8),('Armoire 2 portes','2-door wardrobe',2),('Armoire 3 portes','3-door wardrobe',3),('Commode','Chest of drawers',0.8),('Table de chevet','Bedside table',0.2),('Bureau','Desk',1),('Chaise de bureau','Desk chair',0.3)]),
 ('cuisine','Cuisine & électroménager','Kitchen & appliances',[('Réfrigérateur','Fridge',1),('Réfrigérateur américain','American fridge',1.8),('Congélateur','Freezer',0.8),('Lave-linge','Washing machine',0.6),('Sèche-linge','Tumble dryer',0.6),('Lave-vaisselle','Dishwasher',0.6),('Cuisinière ou four','Cooker or oven',0.6),('Micro-ondes','Microwave',0.1),('Table de cuisine','Kitchen table',0.6)]),
 ('divers','Cave, garage & extérieur','Cellar, garage & outdoor',[('Vélo','Bicycle',0.5),('Étagère de rangement','Storage shelving',0.8),('Salon de jardin','Garden furniture set',1.5),('Barbecue','Barbecue',0.5),('Tondeuse','Lawnmower',0.5),('Valise','Suitcase',0.1)]),
 ('cartons','Cartons','Boxes',[('Carton standard','Standard box',0.1),('Carton livres','Book box',0.05),('Penderie carton','Wardrobe box',0.3)]),
]

def volume_calc():
 rooms=''
 n=0
 for key,fr,en,items in ROOMS:
  rows=''
  for a,c,v in items:
   rows+=f'<li class="vc-row" data-v="{v}" data-label="{t(a,c)}"><span class="vc-name">{t(a,c)}<small>{str(v).replace(".",",") if b.LANG=="fr" else v} m³</small></span><span class="vc-count"><button type="button" class="vc-minus" aria-label="{t("Retirer","Remove")} {t(a,c)}">−</button><output aria-live="off">0</output><button type="button" class="vc-plus" aria-label="{t("Ajouter","Add")} {t(a,c)}">+</button></span></li>';n+=1
  rooms+=f'<details class="vc-room"{" open" if key=="salon" else ""}><summary><span>{t(fr,en)}</span><span class="vc-room-total" data-room-total>0 m³</span></summary><ul>{rows}</ul></details>'
 return f'''<section class="section band-ivory vcalc" id="volume" data-vcalc><div class="wrap vc-grid"><div>{eyebrow('Calculateur de volume','Volume calculator')}<h2>{t('Estimez votre volume,<br><em>pièce par pièce.</em>','Estimate your volume,<br><em>room by room.</em>')}</h2><p class="lead">{t('Ajoutez vos meubles et vos cartons : le volume se calcule au fur et à mesure. Envoyez-le ensuite avec votre demande de devis.','Add your furniture and boxes: the volume updates as you go. Then send it with your quote request.')}</p><div class="vc-rooms">{rooms}</div></div><aside class="vc-total"><span class="eyebrow">{t('Volume estimé','Estimated volume')}</span><p class="vc-m3"><strong data-vc-total>0</strong> m³</p><p class="vc-hint" data-vc-hint>{t('Ajoutez vos premiers meubles.','Add your first items.')}</p><a class="btn btn-cta vc-send" href="{url('devis')}" data-vc-send>{t('Utiliser ce volume dans mon devis','Use this volume in my quote')}</a><button type="button" class="text-link vc-reset" data-vc-reset>{t('Tout remettre à zéro','Reset all')}</button><p class="fine-print">{t('Estimation indicative fondée sur des volumes moyens. Votre conseiller CODEM la confirme avec vous, si besoin lors d’une visite.','Indicative estimate based on average volumes. Your CODEM adviser confirms it with you, with a visit if needed.')}</p></aside></div></section>'''

ECHEANCES=[('','Sélectionner','Select'),('moins-1-mois','Dans moins d’1 mois','Within 1 month'),('1-3-mois','Dans 1 à 3 mois','In 1 to 3 months'),('3-6-mois','Dans 3 à 6 mois','In 3 to 6 months'),('plus-6-mois','Dans plus de 6 mois','In more than 6 months'),('inconnu','Je ne sais pas encore','Not sure yet')]
def guide_section(endpoint):
 opts=''.join(f'<option value="{v}">{t(a,c)}</option>' for v,a,c in ECHEANCES)
 pdf=f"/assets/checklist-demenagement-codem-{b.LANG}.pdf"
 return f'''<section class="section band-navy guide-band" id="checklist-offerte"><div class="wrap guide-grid"><div class="guide-intro"><span class="guide-mascot-box">{b.mascot('checklist','guide-mascot',210)}<span class="bubble guide-bubble"><span class="bubble-name">Cody</span>{t('J’ai tout listé pour vous.','I’ve listed everything for you.')}</span></span>{eyebrow('Offert','Free')}<h2>{t('La checklist complète<br><em>de votre déménagement.</em>','Your complete<br><em>moving checklist.</em>')}</h2><p>{t('De J-60 à J+7 : toutes les démarches, dans l’ordre, au format PDF à imprimer ou à garder sur votre téléphone.','From D-60 to D+7: every step, in order, as a PDF to print or keep on your phone.')}</p></div><form class="guide-form" id="guide-form" data-kind="message" data-endpoint="{endpoint}" novalidate><input type="hidden" name="mode" value="guide"><div class="field"><label for="gd-prenom">{t('Prénom','First name')}</label><input id="gd-prenom" name="prenom" autocomplete="given-name"></div><div class="field"><label for="gd-email">{t('E-mail','Email')}<span data-required> *</span></label><input id="gd-email" name="email" type="email" required autocomplete="email"><span class="field-error"></span></div><div class="field"><label for="gd-echeance">{t('Votre déménagement est prévu…','Your move is planned…')}</label><select id="gd-echeance" name="echeance">{opts}</select></div><label class="check"><input type="checkbox" name="marketing" value="oui"><span>{t('J’accepte de recevoir les conseils et offres de CODEM (facultatif).','I agree to receive CODEM tips and offers (optional).')}</span></label><p class="fine-print">{t('Votre e-mail sert à vous envoyer la checklist ; un conseiller CODEM peut vous recontacter au sujet de votre projet.','Your email is used to send the checklist; a CODEM adviser may contact you about your move.')} <a href="{url('privacy')}">{t('Confidentialité','Privacy')}</a>.</p><div class="honeypot" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><button class="btn btn-cta" type="submit">{t('Recevoir la checklist','Get the checklist')}</button><p class="form-status" role="status" aria-live="polite"></p><div class="guide-done" hidden><p><strong>{t('Merci ! Votre checklist est prête.','Thank you! Your checklist is ready.')}</strong></p><a class="btn" href="{pdf}" download data-guide-pdf>{t('Télécharger la checklist (PDF)','Download the checklist (PDF)')}</a></div></form></div></section>'''
